"""Offline replay of AnswerSpace variants over the recorded runs."""
import json, re, sys, importlib.util
sys.path.insert(0,'/workspace/benchmark')
from data.evaluators import get_evaluator

RUNS = {
 "N0":"9f49dd7221d29df0c6f8b80f8f04a8b2b2b607f7",
 "N1":"b539c7bec6aedea86a01cfab887fab950110c356",
 "N2":"562ab0872291f6e171db9409b3576432d425084c",
 "N3":"57a4d05c3f5fc24a9196220ef26c5254ea360077",
 "N4":"54fcbc3010c5d571ac06d028c53f4671b7219188",
 "N5":"7dacda0afed022c6d09a60aabeaaba4b50a209cb",
}
TASKS=["USPTO","Symptom2Disease","LawBench"]

def load(space_mod):
    spec=importlib.util.spec_from_file_location("memory", "/workspace/harness/solver/tools/memory.py")
    m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    return m

def answers_of(tree, task):
    ex=json.load(open(f"/workspace/runs/{tree}/{task}/memory.json"))["examples"]
    return ex

# ---------------- candidate rule implementations ----------------
SEP = ";；,，、"

def learn_joiner(answers, sep_candidates=SEP):
    """The punctuation that actually joins answers: the one whose parts the memory
    also holds as answers of their own."""
    whole = {a.strip() for a in answers}
    best, best_ratio = None, 0.0
    for sep in sep_candidates:
        parts_total = parts_whole = 0
        for a in whole:
            if sep not in a: continue
            ps=[p.strip() for p in a.split(sep) if p.strip()]
            if len(ps)<2: continue
            parts_total += len(ps)
            parts_whole += sum(1 for p in ps if p in whole)
        if parts_total and parts_whole/parts_total > best_ratio:
            best, best_ratio = sep, parts_whole/parts_total
    return best

def split_answer_learned(answer, joiner):
    if joiner and joiner in answer:
        return [p.strip() for p in answer.split(joiner) if p.strip()]
    return [answer.strip()] if answer.strip() else []

def split_parts_learned(answer, joiner):
    return split_answer_learned(answer, joiner)

def prefix_spelling(unit, units, parts):
    """The memory's answer that this draft part is an under-written beginning of."""
    if unit in units: return None
    cands=[m for m in parts if len(m)>len(unit) and m.startswith(unit)]
    # only where the extension is unique reasoning: the shortest such answer
    if len(cands)==1: return cands[0]
    if cands: return min(cands, key=len)
    return None

class Space:
    def __init__(self, examples, joiner=None, use_prefix=False, legacy=False):
        self.answers=[str(e["target"]) for e in examples]
        if legacy:
            self.joiner=None  # legacy split_answer: first separator found
        else:
            self.joiner = joiner if joiner is not None else learn_joiner(self.answers)
        units=[]
        for a in self.answers:
            if legacy:
                for s in SEP:
                    if s in a:
                        units += [p.strip() for p in a.split(s) if p.strip()]; break
                else: units.append(a.strip())
            else:
                units += split_answer_learned(a, self.joiner)
        from collections import Counter
        self.units=Counter(units)
        self.terminals={u[-1] for u in self.units}
        self.parts=set(self.units)   # whole answers / learned units only
        self.use_prefix=use_prefix

    def draft_units(self, draft):
        # split the draft on the learned joiner; drop markup around it
        from collections import Counter
        text=str(draft)
        m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
        if m: text=m.group(1)
        text=text.replace("<eoa>","")
        return [p.strip() for p in split_answer_learned(text.strip(), self.joiner) if p.strip()]

    def variant(self, unit):
        if len(unit)>2 and unit[-1] not in self.terminals:
            shorter=unit[:-1]
            if shorter in self.parts: return shorter
        if self.use_prefix:
            p=prefix_spelling(unit, self.units, self.parts)
            if p: return p
        return None

    def respell(self, draft):
        out=str(draft)
        for u in self.draft_units(draft):
            v=self.variant(u)
            if v: out=out.replace(u, v)
        return out

def rescore(task, preds, targets):
    ev=get_evaluator(task)
    ok=0
    for p,t in zip(preds,targets):
        r=ev(p,t)
        ok += 1 if (r["was_correct"] if isinstance(r,dict) else r) else 0
    return ok

def run(variant_name, factory):
    print("#"*70); print("VARIANT:", variant_name)
    grand_base=grand_new=0
    for task in TASKS:
        tb=tn=tot=0
        for name,tree in RUNS.items():
            ex=answers_of(tree,task)
            sp=factory(ex)
            rows=[json.loads(l) for l in open(f"/workspace/runs/{tree}/results/samples.jsonl") if json.loads(l)["task"]==task]
            preds=[r["prediction"] for r in rows]; targets=[r["target"] for r in rows]
            newpreds=[sp.respell(p) for p in preds]
            b=rescore(task,preds,targets); n=rescore(task,newpreds,targets)
            tb+=b; tn+=n; tot+=len(rows)
            if b!=n:
                print(f"   {name} {task}: {b} -> {n} / {len(rows)}")
                for r,np in zip(rows,newpreds):
                    if np!=r["prediction"]:
                        ev=get_evaluator(task)
                        r0=ev(r["prediction"],r["target"]); r1=ev(np,r["target"])
                        c0=r0["was_correct"] if isinstance(r0,dict) else r0
                        c1=r1["was_correct"] if isinstance(r1,dict) else r1
                        print(f"       q{r['example_index']:>3} s{r['sample_index']} {c0}->{c1}  {r['prediction'][:50]!r} => {np[:50]!r}   tgt={r['target'][:50]!r}")
        print(f"   TOTAL {task}: {tb} -> {tn} / {tot}")
        grand_base+=tb; grand_new+=tn
    print("   GRAND:",grand_base,"->",grand_new)

run("legacy (current code)", lambda ex: Space(ex, legacy=True))
run("learned-joiner only", lambda ex: Space(ex))
run("learned-joiner + prefix-extension", lambda ex: Space(ex, use_prefix=True))
